    /** The logo and whether it is drawn in its own colors (else tinted). */
    fun of(kind: AiProviderKind): Pair<ImageVector, Boolean>? = when (kind) {
        AiProviderKind.CLAUDE -> CLAUDE to true
        AiProviderKind.OPENAI -> OPENAI to false
        AiProviderKind.GEMINI -> GEMINI to true
        AiProviderKind.GROK -> GROK to false
        AiProviderKind.MISTRAL -> MISTRAL to true
        AiProviderKind.LOCAL -> OLLAMA to false
        AiProviderKind.CUSTOM -> null
    }
}

@Composable
fun ProviderLogo(kind: AiProviderKind, size: Dp = 20.dp, tint: Color = Nt.Text) {
    val logo = ProviderLogos.of(kind)
    when {
        logo == null -> Icon(Icons.Outlined.Hub, contentDescription = null, tint = tint, modifier = Modifier.size(size))
        logo.second -> Image(logo.first, contentDescription = null, modifier = Modifier.size(size))
        else -> Icon(logo.first, contentDescription = null, tint = tint, modifier = Modifier.size(size))
    }
}
